gql-persisted-queries.solution:
function hashQuery(text) {
  let h = 5381;
  for (let i = 0; i < text.length; i++) {
    h = (h * 33 + text.charCodeAt(i)) % 4294967296;
  }
  return h.toString(16).padStart(8, "0");
}

function handleRequests(requests, locked, preregistered) {
  const table = new Map();
  for (const q of preregistered || []) table.set(hashQuery(q), q);
  return requests.map((r) => {
    if (r.query === undefined || r.query === null) {
      return table.has(r.hash)
        ? { status: "OK", query: table.get(r.hash) }
        : { status: "PERSISTED_QUERY_NOT_FOUND" };
    }
    if (hashQuery(r.query) !== r.hash) return { status: "HASH_MISMATCH" };
    if (!table.has(r.hash)) {
      if (locked) return { status: "NOT_ALLOWED" };
      table.set(r.hash, r.query);
    }
    return { status: "OK", query: r.query };
  });
}

gql-query-depth.solution:
def check_depth(query, fragments, max_depth):
    class Cycle(Exception):
        pass

    def depth(selection, active):
        best = 0
        for item in selection:
            if "spread" in item:
                name = item["spread"]
                if name in active:
                    raise Cycle()
                d = depth(fragments[name]["selection"], active | {name})
            else:
                d = 1 + depth(item.get("selection") or [], active)
            if d > best:
                best = d
        return best

    try:
        d = depth(query, frozenset())
    except Cycle:
        return {"depth": None, "allowed": False}
    return {"depth": d, "allowed": d <= max_depth}

