def complexity(query, costs):
    def score(node):
        args = node.get("args") or {}
        if "first" in args:
            m = args["first"]
        elif "last" in args:
            m = args["last"]
        else:
            m = 1
        children = sum(score(c) for c in node.get("selection") or [])
        return costs.get(node["name"], 1) + m * children

    return sum(score(n) for n in query)

